SELECT r."failure_json", r."report_id", r."active_version_no", r."desired_generation", r."publication_status", r."spec_hash", r."published_by", r."published_at", r."active_generation", r."runtime_revision", r."activated_at", r."desired_version_no" FROM (SELECT publication."report_id", publication."active_version_no", publication."desired_generation", publication."active_generation", publication."publication_status", publication."runtime_revision", publication."spec_hash", publication."published_by", publication."published_at", publication."activated_at", publication."failure_json", publication."desired_version_no" FROM  (SELECT p.* FROM report_publications p
)  publication WHERE 1 = 1) r WHERE $criteria.CompositeIn("r", $PublicationKeys)